32: function makeSky(){const sky=new THREE.Mesh(new THREE.SphereGeometry(280,32,20),new THREE.MeshBasicMaterial({color:0x9ab5ad,side:THREE.BackSide}));scene.add(sky);const sun=new THREE.Mesh(new THREE.SphereGeometry(5,20,16),new THREE.MeshBasicMaterial({color:0xffe9ad}));sun.position.set(-80,85,-140);scene.add(sun);const glow=new THREE.Mesh(new THREE.SphereGeometry(10,16,12),new THREE.MeshBasicMaterial({color:0xffdf9a,transparent:true,opacity:.11}));glow.position.copy(sun.position);scene.add(glow)}
33: function makeGround(){const n=130,size=210,geo=new THREE.PlaneGeometry(size,size,n,n);geo.rotateX(-Math.PI/2);const p=geo.attributes.position,colors=[];const c1=new THREE.Color(0x57694b),c2=new THREE.Color(0x7d8057),c3=new THREE.Color(0x52644d);for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i),h=terrainHeight(x,z);p.setY(i,h);let c=(Math.sin(x*.13+z*.08)*.5+.5)>.68?c2:c1;if(Math.abs(x)<4 && z<15 && z>-28)c=c3;const v=.88+Math.sin(x*.22)*.035+Math.cos(z*.19)*.04;colors.push(c.r*v,c.g*v,c.b*v)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const g=mesh(geo,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));g.receiveShadow=true;}
34: function makeMountains(){const rand=seeded(88);for(let ring=0;ring<2;ring++){const count=ring?28:20,rad=ring?95:125;for(let i=0;i<count;i++){const a=i/count*Math.PI*2+rand()*.16,r=rad+rand()*12,h=19+rand()*(ring?19:35),w=8+rand()*13;const geo=new THREE.ConeGeometry(w,h,5);const m=mesh(geo,mat(ring?0x56635d:0x77877b));m.position.set(Math.cos(a)*r,h*.43-5,Math.sin(a)*r-14);m.rotation.y=rand()*6.2;m.rotation.z=(rand()-.5)*.12}}}
35: function makeRiver(){const points=[];for(let i=0;i<=12;i++){const z=-72+i*12;points.push(new THREE.Vector3(27+Math.sin(i*.68)*7,-.12,z))}const curve=new THREE.CatmullRomCurve3(points);const geo=new THREE.TubeGeometry(curve,100,2.6,8,false);const water=mesh(geo,new THREE.MeshStandardMaterial({color:0x587f80,roughness:.18,metalness:.22,transparent:true,opacity:.8}));water.castShadow=false;}
36: function makeTree(x,z,scale=1,kind=0){const y=terrainHeight(x,z),g=new THREE.Group();g.position.set(x,y,z);g.scale.setScalar(scale);scene.add(g);let trunk=mesh(new THREE.CylinderGeometry(.18,.34,3.8,7),mat(kind?0x57452f:0x5e4932),g);trunk.position.y=1.5;trunk.castShadow=true;if(kind===1){for(let i=0;i<4;i++){const b=mesh(new THREE.ConeGeometry(1.25-i*.18,2.7,7),mat(i%2?0x365448:0x42634e),g);b.position.set(0,2.5+i*1.1,0)}}else{const crown=mesh(new THREE.IcosahedronGeometry(1.75,1),mat(kind===2?0x5a6550:(scale>1.1?0x3e5a43:0x557252)),g);crown.position.y=3.55;crown.scale.set(1,1.05,.94);for(let i=0;i<3;i++){const cl=mesh(new THREE.IcosahedronGeometry(.9,0),mat(kind===2?0x798067:0x65825c),g);cl.position.set((i-1)*.92,3.1+(i%2)*.7,.3)}}decor.push(g);return g}
37: function makeForest(){const rand=seeded(185);for(let i=0;i<210;i++){let x=(rand()-.5)*190,z=(rand()-.5)*180-15;if(Math.abs(x)<20&&z<16&&z>-39)continue;if(x>20&&x<43)continue;makeTree(x,z,.72+rand()*.78,rand()<.25?1:0)}for(let i=0;i<35;i++){let x=(rand()-.5)*170,z=(rand()-.5)*170; if(Math.abs(x)<22&&z<10&&z>-30)continue;let r=.5+rand()*1.5,m=mesh(new THREE.IcosahedronGeometry(r,0),mat(rand()<.5?0x77796a:0x666d60));m.position.set(x,terrainHeight(x,z)+r*.45,z);m.scale.y=.7;decor.push(m)}}
38: function cabin(x,z,scale=1,accent=0x9b6244){const g=new THREE.Group();g.position.set(x,terrainHeight(x,z),z);g.scale.setScalar(scale);scene.add(g);const body=box(g,0,1.45,0,5.6,3,4.5,0x806248);body.rotation.y=.025;const roofGeo=new THREE.ConeGeometry(4.5,2.8,4);const roof=mesh(roofGeo,mat(0x443c32),g);roof.position.set(0,4.22,0);roof.rotation.y=Math.PI/4;roof.scale.set(1,.82,.8);const door=box(g,0,.92,2.27,.95,1.85,.12,0x382a20);const win1=box(g,-1.7,1.8,2.3,.55,.65,.1,accent);const win2=box(g,1.7,1.8,2.3,.55,.65,.1,accent);for(let i=-1;i<=1;i++){const log=box(g,i*1.4,1.15,2.34,.12,2.65,.12,0x583f2b)}const chimney=box(g,1.45,4.4,-.7,.55,2,.55,0x665345);chimney.position.y=4.35;return g}
39: function makeVillage(){cabin(-16,-13,1.3,0xba7954);cabin(-28,-20,.9,0xb98a5b);cabin(-13,-30,.86,0x9a6145);cabin(2,-23,.9,0xa87a4c);const path=new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([new THREE.Vector3(0,terrainHeight(0,9)+.04,9),new THREE.Vector3(-3,terrainHeight(-3,0)+.04,0),new THREE.Vector3(-10,terrainHeight(-10,-8)+.04,-8),new THREE.Vector3(-16,terrainHeight(-16,-16)+.04,-16)]),32,.95,6,false),mat(0x766346));path.castShadow=false;scene.add(path);for(let i=0;i<6;i++){const x=-20+i%3*3,z=-17+Math.floor(i/3)*3;const post=box(scene,x,terrainHeight(x,z)+1,z,.16,2,.16,0x64482c);const fire=new THREE.PointLight(0xff9b43,1.2,8);fire.position.set(x,2,z);scene.add(fire);const f=mesh(new THREE.ConeGeometry(.16,.65,6),new THREE.MeshBasicMaterial({color:0xffa64c}));f.position.set(x,2,z)}}
40: function makeRuin(){const x=48,z=-47,y=terrainHeight(x,z),base=box(scene,x,y+1,z,15,2,12,0x55584c);base.material=mat(0x65685b);for(const [dx,dz,h] of [[-6,-4,7],[6,-4,8],[-6,4,5],[6,4,7]]){const c=mesh(new THREE.CylinderGeometry(.65,.85,h,7),mat(0x878675));c.position.set(x+dx,y+1+h/2,z+dz);const cap=mesh(new THREE.BoxGeometry(1.8,.4,1.8),mat(0x9a987f));cap.position.set(x+dx,y+1+h,z+dz)}for(let i=0;i<5;i++){const col=box(scene,x-4+i*2,y+3.8,z-4,.18,4,.2,0xa27b48);const gem=mesh(new THREE.OctahedronGeometry(.25),new THREE.MeshStandardMaterial({color:0xffa64b,emissive:0xff6112,emissiveIntensity:2}));gem.position.set(x-4+i*2,y+5.9,z-4)}world.waystone=new THREE.Vector3(x,y,z)}
41: function makePlayer(){player=new THREE.Group();scene.add(player);player.position.copy(state.position);const rig=new THREE.Group();player.add(rig);player.userData.rig=rig;const robeColor=state.path==='Ranger'?0x485c43:state.path==='Spellblade'?0x45496a:0x59645b;const torso=mesh(new THREE.CylinderGeometry(.37,.52,1.1,8),mat(robeColor),rig);torso.position.y=1.35;const belt=mesh(new THREE.CylinderGeometry(.4,.42,.15,8),mat(0x9a7040),rig);belt.position.y=1.2;const head=mesh(new THREE.SphereGeometry(.31,12,10),mat(state.race==='Fellborn'?0x9c6a50:state.race==='Sylvan'?0xc19776:0xd0a47b),rig);head.position.y=2.16;const hair=mesh(new THREE.SphereGeometry(.33,10,8),mat(state.race==='Sylvan'?0x5c6846:0x4c352a),rig);hair.position.set(0,2.32,-.035);hair.scale.set(1,.58,1);const legs=[];for(const x of [-.21,.21]){const leg=mesh(new THREE.CylinderGeometry(.14,.18,.77,7),mat(0x343b35),rig);leg.position.set(x,.47,0);legs.push(leg)}const arms=[];for(const x of [-.49,.49]){const arm=mesh(new THREE.CylinderGeometry(.12,.16,.78,7),mat(robeColor),rig);arm.position.set(x,1.4,0);arm.rotation.z=x<0?-.18:.18;arms.push(arm)}const blade=mesh(new THREE.BoxGeometry(.09,.8,.13),new THREE.MeshStandardMaterial({color:0xc9c5b2,metalness:.65,roughness:.27}),rig);blade.position.set(.56,1.15,.1);blade.rotation.z=-.2;const hilt=mesh(new THREE.BoxGeometry(.25,.07,.16),mat(0x987044),rig);hilt.position.set(.56,.78,.1);player.userData.parts={legs,arms,blade};}
42: function makeKeeper(){const g=new THREE.Group();g.position.set(-16,terrainHeight(-16,-9),-9);scene.add(g);const cloak=mesh(new THREE.CylinderGeometry(.35,.52,1.2,8),mat(0x806a42),g);cloak.position.y=1.3;const head=mesh(new THREE.SphereGeometry(.28,12,10),mat(0xd0a582),g);head.position.y=2.15;const hood=mesh(new THREE.ConeGeometry(.42,.55,7),mat(0x4f5848),g);hood.position.y=2.45;const staff=mesh(new THREE.CylinderGeometry(.035,.06,2.5,6),mat(0x58402d),g);staff.position.set(.55,1.3,0);const marker=mesh(new THREE.OctahedronGeometry(.23),new THREE.MeshStandardMaterial({color:0xffd77e,emissive:0x9b591d,emissiveIntensity:1.6}),g);marker.position.y=3.1;world.keeper=g;}
43: function makePickups(){const spots=[[-38,-43],[18,-54],[54,-28]];spots.forEach((p,i)=>{const y=terrainHeight(...p);const g=new THREE.Group();g.position.set(p[0],y+.7,p[1]);scene.add(g);const shard=mesh(new THREE.OctahedronGeometry(.48,0),new THREE.MeshStandardMaterial({color:0xff9b4a,emissive:0xb8480d,emissiveIntensity:1.6,metalness:.25,roughness:.24}),g);shard.scale.set(.65,1.5,.65);const ring=mesh(new THREE.TorusGeometry(.68,.035,6,24),new THREE.MeshBasicMaterial({color:0xffc478}));ring.rotation.x=Math.PI/2;g.add(ring);const light=new THREE.PointLight(0xff8033,.8,7);g.add(light);g.userData={type:'shard',index:i,active:true};pickups.push(g)})}
